function bfs(array $graph, string $start): array {
    $seen = [$start => true];
    $queue = [$start];
    $order = [];

    while ($queue !== []) {
        $node = array_shift($queue);
        $order[] = $node;

        foreach ($graph[$node] ?? [] as $next) {
            if (! isset($seen[$next])) {
                $seen[$next] = true;
                $queue[] = $next;
            }
        }
    }

    return $order;
}

function dfs(array $graph, string $node, array &$seen = [], array &$order = []): array {
    if (isset($seen[$node])) {
        return $order;
    }

    $seen[$node] = true;
    $order[] = $node;

    foreach ($graph[$node] ?? [] as $next) {
        dfs($graph, $next, $seen, $order);
    }

    return $order;
}
